onTurnStart.script:
// === Burn DOT v2 (Effect Macro → On Combat Turn Starting) ==================
// Deals % Max HP fire damage via your Advance Damage macro, *without* UI
// targeting flicker (uses headless targetIds override).
//
// • Default: 10% of max HP
// • Champion rank (NPC): 5%
// • PCs (no rank field): 10%
// • Element: "fire", Weapon type: "none_ef"
//
// Requires: AdvanceDamage patched to accept __PAYLOAD.targetIds when __AUTO=true.
// Macro name below must match your macro exactly.
// ===========================================================================

(async () => {
  const ADV_DMG_MACRO_NAME = "AdvanceDamage"; // <-- change if yours is named differently

  // --- Guard: must be owner’s actual turn ----------------------------------
  if (!actor || !game.combat) return;
  const isOwnersTurn = game.combat?.combatant?.actor?.id === actor.id;
  if (!isOwnersTurn) return;

  // --- Resolve the correct token id for this actor on this turn ------------
  function pickTokenIdForActor(a) {
    // Prefer the current combatant token if it belongs to this actor
    const ct = game.combat?.combatant;
    if (ct?.actor?.id === a.id && ct.token?.id) return ct.token.id;

    // Else use module helper `token` if provided
    if (token?.id) return token.id;

    // Else first active token on the viewed scene
    const t = a.getActiveTokens()?.[0];
    return t?.id ?? t?.document?.id ?? null;
  }
  const tokenId = pickTokenIdForActor(actor);
  if (!tokenId) return ui.notifications.warn("[Burn] No active token for effect owner.");

  // --- Determine DOT percent from NPC rank ---------------------------------
  // NPC sheet sample uses system.props.npc_rank with values like "sol","eli","cha"
  const props = actor.system?.props ?? {};
  const rank  = String(props.npc_rank ?? "").toLowerCase();
  const percent = (rank === "cha") ? 5 : 10;  // PCs or missing rank → 10%

  // --- Build headless payload for AdvanceDamage ----------------------------
  const payload = {
    // magnitude as a percent number (no % sign)
    baseValue: String(percent),
    valueType: "hp",
    targetAffinity: "percentMax",   // make ADV compute % of target's max HP
    elementType: "fire",
    weaponType: "none_ef",
    ignoreDamageReduction: false,
    ignoreShield: false,

    // nice-to-have context for your logs/cards
    attackerName: "Burn",
    attackRange: "DOT",
    sourceType : "Effect: Burn",

    // HEADLESS target override (prevents crosshair UI)
    targetIds: [tokenId]
  };

  // --- Execute your universal damage macro ---------------------------------
  const ADV = game.macros.getName(ADV_DMG_MACRO_NAME);
  if (!ADV) return ui.notifications.error(`[Burn] Macro "${ADV_DMG_MACRO_NAME}" not found.`);

  await ADV.execute({ __AUTO: true, __PAYLOAD: payload });
})();
